import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"AI Learning Log: From Tool Collaboration to Independent Ability","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/ai-learning-log.en.md","filePath":"public/downloads/worksheets/ai-learning-log.en.md","lastUpdated":1795488252000}'),i={name:"public/downloads/worksheets/ai-learning-log.en.md"};function o(d,e,l,s,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-learning-log-from-tool-collaboration-to-independent-ability" tabindex="-1">AI Learning Log: From Tool Collaboration to Independent Ability <a class="header-anchor" href="#ai-learning-log-from-tool-collaboration-to-independent-ability" aria-label="Permalink to &quot;AI Learning Log: From Tool Collaboration to Independent Ability&quot;">​</a></h1><p>Record one inspectable learning slice at a time. An AI-generated summary, score, or explanation is not a source of truth; original material, your first version, actual work, and real feedback are evidence. Do not write “what I discussed with the model”. Write “what I can still complete independently after the tool leaves”.</p><h2 id="_1-task-and-starting-point" tabindex="-1">1. Task and Starting Point <a class="header-anchor" href="#_1-task-and-starting-point" aria-label="Permalink to &quot;1. Task and Starting Point&quot;">​</a></h2><h3 id="ai-learning-log-yyyy-mm-dd" tabindex="-1">AI Learning Log - YYYY-MM-DD <a class="header-anchor" href="#ai-learning-log-yyyy-mm-dd" aria-label="Permalink to &quot;AI Learning Log - YYYY-MM-DD&quot;">​</a></h3><p>Real situation and audience:<br> Main question:<br> Action and acceptance standard:<br> Material, version, and source:<br> Time, device, and environment limits:<br> Permitted dictionary / translation / search / AI / human help:<br> Privacy, copyright, exam, and ownership boundary:</p><h2 id="_2-unaided-baseline" tabindex="-1">2. Unaided Baseline <a class="header-anchor" href="#_2-unaided-baseline" aria-label="Permalink to &quot;2. Unaided Baseline&quot;">​</a></h2><p>Start/end time of independent attempt:<br> Unaided sample location:<br> What I could explain or complete:<br> Errors, unknowns, and judgment blind spots exposed:<br> Confidence (0-2):</p><p>Do not ask AI to write an answer first and call that the starting point. If the task permits a dictionary or documentation, record the permitted support; the baseline states what you can do independently under those conditions.</p><h2 id="_3-agree-what-ai-does" tabindex="-1">3. Agree What AI Does <a class="header-anchor" href="#_3-agree-what-ai-does" aria-label="Permalink to &quot;3. Agree What AI Does&quot;">​</a></h2><p>Model / version / date:<br> Input mode: text / audio / image / video / mixed<br> Context, retrieved material, and memory settings actually supplied:<br> Task/run IDs, trace, and checkpoint locations:<br> Whether browser pages, screenshots, and external links were treated as untrusted input:<br> Network egress, tool authorization, and external-write receipt:<br> Mode: diagnosis / follow-up / explanation / counterexample / transcript / candidate / other<br> AI may:<br> AI may not:<br> Minimum material sent:<br> Fields or files withheld:</p><p>Move one slice per round. Ask the model to identify gaps, assumptions, sources, and uncertainty before requesting any rewrite or candidate.</p><h2 id="_4-interaction-and-source-verification" tabindex="-1">4. Interaction and Source Verification <a class="header-anchor" href="#_4-interaction-and-source-verification" aria-label="Permalink to &quot;4. Interaction and Source Verification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Turn</th><th>My question/action</th><th>Model suggestion</th><th>Type</th><th>Source/uncertainty</th><th>My decision</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>explanation / question / candidate / feedback / code / other</td><td></td><td>accept / partly / reject / verify</td></tr></tbody></table><p>Primary sources I checked:<br> Original audio, image, or video location and timestamp / page / image region:<br> Transcription, visual-recognition, or citation errors, separate from my knowledge errors:<br> Errors, outdated claims, or invented material I found:<br> Suggestions that changed my understanding and why:<br> Suggestions that changed only surface wording:</p><p>People confirm sources, facts, permissions, privacy, and final judgment. Model confidence does not raise the evidence level.</p><h2 id="_5-active-production-after-closing-ai" tabindex="-1">5. Active Production After Closing AI <a class="header-anchor" href="#_5-active-production-after-closing-ai" aria-label="Permalink to &quot;5. Active Production After Closing AI&quot;">​</a></h2><p>Time AI was closed:<br> Work, explanation, code, or decision completed independently:<br> Independent time:<br> Cues still required:<br> Can I explain every critical step? yes / partly / no<br> Test, reader/user feedback, or run result:</p><h2 id="_6-three-comparisons" tabindex="-1">6. Three Comparisons <a class="header-anchor" href="#_6-three-comparisons" aria-label="Permalink to &quot;6. Three Comparisons&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sample</th><th>Conditions</th><th>Task/quality</th><th style="text-align:right;">Time</th><th style="text-align:right;">Rework</th><th style="text-align:right;">Confidence</th><th>Evidence location</th></tr></thead><tbody><tr><td>Unaided baseline</td><td></td><td></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>AI-assisted version</td><td></td><td></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Delayed independent (3-7 days)</td><td></td><td></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Parallel task (changed condition)</td><td></td><td></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Result</th><th>Cautious interpretation</th></tr></thead><tbody><tr><td>Assisted and independent versions improve</td><td>A removable scaffold may be forming; test more transfer</td></tr><tr><td>Only assisted version improves</td><td>Product improved; critical steps may be outsourced</td></tr><tr><td>Time falls while rework rises</td><td>Speed created speed debt</td></tr><tr><td>Confidence rises while facts/tests fall</td><td>Calibrate judgment before increasing tool access</td></tr></tbody></table><p>One comparison cannot prove causality, but it records contribution more clearly than “AI was useful”.</p><h2 id="_7-errors-feedback-and-transfer" tabindex="-1">7. Errors, Feedback, and Transfer <a class="header-anchor" href="#_7-errors-feedback-and-transfer" aria-label="Permalink to &quot;7. Errors, Feedback, and Transfer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error/gap</th><th>Sample</th><th>Type</th><th>Change only this next</th><th>Parallel-task result</th></tr></thead><tbody><tr><td></td><td></td><td>fact / vocabulary / structure / grammar / strategy / attention / tool dependence</td><td></td><td></td></tr></tbody></table><p>Real reader/user retelling or execution result:<br> Feedback accepted, partly accepted, rejected, or deferred and why:<br> Action that survived a changed topic/audience/mode/time:<br> Action that still succeeds only on the original task:</p><h2 id="_8-delayed-retention-and-handover" tabindex="-1">8. Delayed Retention and Handover <a class="header-anchor" href="#_8-delayed-retention-and-handover" aria-label="Permalink to &quot;8. Delayed Retention and Handover&quot;">​</a></h2><p>Day 1: what I removed and completed independently:<br> Days 3-7: what changed and what happened:<br> Day 14: can I explain and use it after closing the old chat:<br> Day 30: did the real task require less guessing or rework:<br> State-file location:<br> Last run/recovery ID and final environment state:<br> Can I resume in a new conversation or another tool using only this state file:<br> Handover owner, date, and access:<br> Stop or rollback condition:</p><h2 id="_9-next-cycle-decision" tabindex="-1">9. Next Cycle Decision <a class="header-anchor" href="#_9-next-cycle-decision" aria-label="Permalink to &quot;9. Next Cycle Decision&quot;">​</a></h2><p>What the tool genuinely helped:<br> Risk or dependence the tool created:<br> Evidence of ability I now own:<br> Conclusion still unsupported:<br> Continue / downgrade / change variable / pause / seek help:<br> Smallest next task:<br> Next review date:</p><p>Related entry points: <a href="https://byoungd.github.io/up/en/threads/part-1/1-understanding" target="_blank" rel="noreferrer">Learning Principles: Turn Effort into Verifiable Learning</a> | <a href="https://byoungd.github.io/up/en/threads/part-3/1-ai-learning" target="_blank" rel="noreferrer">Learning Anything with AI</a> | <a href="https://byoungd.github.io/up/en/templates/ai-task-brief" target="_blank" rel="noreferrer">AI Task Brief</a> | <a href="https://byoungd.github.io/up/en/templates/learning-state" target="_blank" rel="noreferrer">Learning State</a> | <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/ai-learning-log" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-10-16. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',31)])])}const b=t(i,[["render",o]]);export{u as __pageData,b as default};
